namespace ghidra.app.util.dialog;






using docking;
using docking;
using docking.widgets.label;
using ghidra.app.util;
using ghidra.program.model.address;
using ghidra.program.model.listing;

public class AskAddrDialog : DialogComponentProvider {
	private bool isCanceled;
	private AddressInput addrInput;

	public AskAddrDialog(string title, string message, Program program,
			Address lastAddr) : base(title, true, true, true, false)
    {

		addrInput = new AddressInput(program);
		if (lastAddr != null) {
			addrInput.setAddress(lastAddr);
		}
		addrInput.select();

		JPanel panel = new JPanel(new BorderLayout(10, 10));
		panel.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		panel.add(new GLabel(message), BorderLayout.WEST);
		panel.add(addrInput, BorderLayout.CENTER);

		addWorkPanel(panel);
		addOKButton();
		addCancelButton();
		setDefaultButton(okButton);

		DockingWindowManager.showDialog(null, this);
	}

	/* @Override */
	protected void okCallback() {
		isCanceled = false;
		if (addrInput.getAddress() == null) {
			setStatusText("Please enter a valid ADDRESS.");
			return;
		}
		close();
	}

	/* @Override */
	protected void cancelCallback() {
		isCanceled = true;
		close();
	}

	public bool isCanceled() {
		return isCanceled;
	}

	public Address getValueAsAddress() {
		return addrInput.getAddress();
	}
}
